  <style>
    :root {
      color-scheme: dark;
      --bg: #0b1020;
      --panel: #131a2d;
      --panel-strong: #1a2340;
      --text: #edf2ff;
      --muted: #b3bfdc;
      --accent: #8b5cf6;
      --accent-strong: #a78bfa;
      --border: #2c3658;
      --shadow: 0 22px 60px rgba(0, 0, 0, 0.42);
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
      min-height: 100vh;
      font-family: Inter, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      background:
        radial-gradient(circle at top, rgba(139, 92, 246, 0.22), transparent 35%),
        linear-gradient(180deg, #111827 0%, var(--bg) 100%);
      color: var(--text);
    }

    .skip-link {
      position: absolute;
      top: 0;
      left: 0;
      transform: translateY(-120%);
      padding: 0.75rem 1rem;
      background: var(--text);
      color: #111827;
      z-index: 10;
    }

