      margin-bottom: 2rem;
      padding: 2rem;
      border: 1px solid rgba(167, 139, 250, 0.24);
      border-radius: 1.5rem;
      background: rgba(19, 26, 45, 0.88);
      box-shadow: var(--shadow);
      backdrop-filter: blur(12px);
    }

