      display: inline-block;
      margin: 0 0 0.75rem;
      padding: 0.35rem 0.7rem;
      border-radius: 999px;
      background: rgba(139, 92, 246, 0.15);
      color: var(--accent-strong);
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.04em;
      text-transform: uppercase;
    }

