      margin: 0;
      color: var(--muted);
      line-height: 1.7;
    }

    .faq-list {
      display: grid;
      gap: 1rem;
    }

    .example {
      overflow: hidden;
      border: 1px solid var(--border);
      border-radius: 1.25rem;
      background: linear-gradient(180deg, rgba(26, 35, 64, 0.95), rgba(19, 26, 45, 0.95));
      box-shadow: var(--shadow);
    }

