      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
      width: 100%;
      padding: 1.15rem 1.25rem;
      border: 0;
      background: transparent;
      color: var(--text);
      font: inherit;
      font-size: 1.05rem;
      font-weight: 700;
      text-align: left;
      cursor: pointer;
    }

    .faq-trigger:hover {
      background: rgba(255, 255, 255, 0.03);
