        answer: "A cat's tail can signal mood and attention. Slow swishes may mean focus or curiosity, while sharp flicks can suggest irritation, overstimulation, or a warning to give them space."
      },
      {
        question: "Do indoor cats still need enrichment?",
        answer: "Yes. Indoor cats benefit from scratching posts, climbing spots, puzzle feeders, window views, and short interactive play sessions that let them stalk, chase, and pounce in safe ways."
      }
    ];

    function Hero() {
      return `
        <section class="hero" aria-labelledby="page-title">
          <p class="eyebrow">Cat care basics</p>
          <h1 id="page-title">Frequently asked questions about cats</h1>
          <p>Explore quick answers about common feline habits, body language, and daily needs. Each question starts collapsed and can be expanded when you want more detail.</p>
        </section>
      `;
    }

    function FaqItem(item, index) {
      const buttonId = `faq-button-${index}`;
      const panelId = `faq-panel-${index}`;

      return `
