            id="${buttonId}"
            class="faq-trigger"
            type="button"
            aria-expanded="false"
            aria-controls="${panelId}"
          >
            <span>${item.question}</span>
            <svg class="icon" viewBox="0 0 24 24" aria-hidden="true">
              <path fill="currentColor" d="M11 4h2v16h-2zM4 11h16v2H4z"></path>
            </svg>
          </button>
          <div
            id="${panelId}"
            class="details"
            role="region"
            aria-labelledby="${buttonId}"
            hidden
          >
            <p>${item.answer}</p>
          </div>
        </div>
      `;
    }

    function FaqList(items) {
      return `
        <section aria-label="Cat FAQ">
